import json,runpy
from pathlib import Path
S=Path(__file__).resolve().parents[1];data=json.loads((S/'data/catalog.json').read_text(encoding='utf8'))
base=runpy.run_path(str(S/'work/write_bds_simple.py'))['base']
base.update({'KBAR間隔ex':'以開始交易時間作分鐘相位起點；n表示每n分、a/n表示每n分的第a相位。小於等於1不篩選，篩選僅作用單條策略進出。','開始交易時間':'此版本主要作KBAR相位起點；未以一般起始時間禁止交易。','最後交易時間':'此版本未用作進場截止或到時平倉。','移停增量比':'此舊版沒有把增量比加入移停距離，不生效。','直停限價':'此版先將high/low/close覆成open，未根據此旗標改用原K棒高低價。','多空進場比':'多空共用的基準突破距離，%依基準價換算，純數字當點數；再與最少進場點取大值。','多進場比':'基準上方多頭目標距離，可獨立於空頭設定；與最少進場點取大值。','空進場比':'基準下方目標距離，可獨立於多頭設定；BDSBuy在下側觸發仍做多。','最少進場點':'上下突破距離下限，最後目標價按商品tick四捨五入。','最多進場次數':'各子策略的總進場次數（多空合計）；退出後已進次數恰等於此值才停止，非僅計停損。','BD線濾網點':'新曆日首筆open與所有仍啟動基準價的距離小於此點數時，不新增該日基準。','停損比':'進場參考價加／減距離的固定保護線；已經有移停線後不再檢查固定停損。','啟動移停比':'由進場參考價換算開始追蹤有利報價的門檻；達到後再更新移停線。','移停拉回比':'從最新有利open回撤的距離；%按該方向的進場目標價換算。','直接停利比':'進場時計算固定目標，但此版只有已存在移停線時才檢查直接停利，不是從開倉起即生效。','最多進場口數':'每筆報價執行前有號淨部位絕對值的上限，0不限制；達上限時直接停止候選，並非總多空曝險上限。','自動停止天數':'在新曆日累加存續天數，達門檻且當時空手才停止；0不作用，不會直接平掉在倉策略。','總停利':'先合計仍持倉子策略以當筆open退出的損益（含出場滑價），達門檻即平倉並停止有倉者；不包含已完成交易獲利。','ATR平均':'進出場距離分別使用的ATR平均方法，SMA或EMA。','進場ATR天數':'進場目標距離所用ATR期數；取不到ATR時改用當時基準價1%作ATR。','出場ATR天數':'停損、直停與移停所用ATR平均期數；每次入場／刷新移停時重新取當日ATR，缺值改取相關目標價1%。'})
core_exit=['有移停線時，先檢查直接停利再檢查回撤；尚無移停線時，只檢查固定停損。固定停損後可同一報價立即測另一側進場。','最後再檢查移停啟動並更新保護線；已進次數達設定總次數後，於退出時停止。直接停利與移停退出會停止該子策略。','結算事件將基準、目標及保護價按價差平移，在倉者另記平舊開新及成本。回測資料結尾只將啟動策略標停止，沒有額外將在倉部位平掉。']
mechanics=['每個曆日首筆ds1m.open嘗試建立一條基準，先執行既有策略由新到舊，再建立當日新線。多條線可同時存續，單次固定一口。','單條策略先過KBAR分鐘相位，然後將high／low／close全覆成open，因此進出及一般停損停利實際只用open。跳過的K棒不會觸發單條保護。','同一報價已有一條線進場時，其他已跨目標的候選會直接停止；跳空進場會將整組基準與目標平移，成交目標因而對齊當筆open。']
caveats=['直接停利只放在已有移停線分支，啟動移停前即使價已越直接停利仍不直接退出。','回測結尾標停止不等於平倉；未平部位可能留在交易報表，不能把所有最後未實現損益當作已實現績效。','最多次數使用已進==設定值，0並非停止進場，若狀態已超過門檻也不會因>=而自動停。','不使用共用金額轉口數，資金管理與ATR風險口數欄位不會改變固定一口部位。']
path=S/'analysis/SuperBDS.json';res=json.loads(path.read_text(encoding='utf8'))
for name in ['StgBDS','StgBDSv2','StgBDSBuy','StgBDSA']:
 a={'family':'通道與突破','summary':'','entry':[],'exit':list(core_exit),'mechanics':list(mechanics),'caveats':list(caveats)};n=dict(base)
 if name=='StgBDS':
  a['summary']='以每日首筆開盤建立BD基準，向上突破做多、向下突破做空；停損後可再進，移停或直接停利後結束該線。'
  a['entry']=['上下目標=基準價±max(最少進場點,多空進場距離)，按商品tick取整。空手先測多後測空，含等號觸發。']
 elif name=='StgBDSA':
  a['summary']='每日BD基準突破策略的ATR距離版本：上下進場及出場保護可按各自ATR平均計算，實際下單仍固定一口。'
  a['entry']=['先計進場／出場兩組ATR平均，進場距離以進場ATR代替價格作百分比換算基底，再與最少進場點取大。','缺ATR時用當筆基準價1%代替；觸發後停損、移停啟動與直停距離改以入場當日的出場ATR換算。']
  a['exit'].insert(0,'移停刷新時重新讀當日出場ATR，%距離按該ATR計算；若跨日ATR變化，即使同樣有利價格也可能改變拉回距離。')
  for k in ['停損比','啟動移停比','直接停利比']:n[k]='距離字串%相對出場ATR換算，純數字仍當點數；缺ATR時用入場目標價1%代替。'+('直接停利仍只有已有移停線時檢查。' if k=='直接停利比' else '')
  n['移停拉回比']='最新有利open加／減按當日出場ATR換算的拉回距離；跨日會重新讀ATR，非固定入場ATR。'
  n['多空進場比']='%相對進場ATR換算，純數字當點數；與最少進場點取大，不是以整個商品價格計百分比。'
 else:
  a['summary']='以每日BD基準的兩側距離觸發'+('皆買多的一口策略；下側觸發時把多目標改到原空目標，保留向下觸發的名稱但實際是多單。' if name=='StgBDSBuy' else '雙向一口交易，另有存續天數、淨部位容量與全體持倉停利。')
  a['entry']=['上下目標分別按多進場比與空進場比換算，與最少進場點取大後加／減基準。觸發含等號，跳空會平移整組價格到open。','容量用本根執行前的啟動中有號部位快照；達淨口數上限時停止候選。新曆日只會自停已過存續天數且空手的線。']
  if name=='StgBDSBuy':
   a['entry'].append('下側目標被觸發時將目標多設為原目標空，仍以B買入；之後走多單的停損、移停與停利，並非跌破後放空。')
   a['caveats'].append('沿用多單停損後檢查下側觸發的路徑，可能同筆停損後又買多，不能將標記空進視為空頭交易。')
  else:
   a['exit'].insert(0,'每根先按open合計持倉尚未實現損益並比較總停利，達標只平並停有部位者，空手候選仍可繼續，之後也可能畫新線。')
   a['caveats'].append('總停利與口數快照位於KBAR篩選外，並不隨單條報價間隔一起降低頻率；容量快照未在本根平倉後立即重算。')
 item=next(i for i in data['items'] if i['id']=='SuperBDS/'+name)
 a['parameterNotes']={p['name']:n[p['name']] for p in item['parameters']};res[item['id']]=a
path.write_text(json.dumps(res,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
print('Wrote SuperBDS',len(res))
